'use strict';
const $=id=>document.getElementById(id),SAVE_KEY='ashen-mercenary-dev-v07';
let loaded=null,storageOK=true;try{loaded=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');}catch(e){}
const engine=new AdventureEngine(loaded);let tab='adventure',selectedItem=null,compact=true,noticeUntil=0,hireCount=1,lastBossClear=null;const caches={};
if(loaded?.version===7){if(engine.s.mode==='combat'){engine.s.mode=loaded.bossInProgress?'camp':'exploring';if(loaded.bossInProgress)engine.s.resume=false;}const gap=(Date.now()-engine.s.savedAt)/1000;if(gap>15)engine.offline(gap);}engine.emit('欢迎回来。先查看生命、目的地与部队，再安排冒险。','system');
const fmt=n=>Math.round(n||0).toLocaleString('zh-CN');
const compactNum=n=>n>=1e9?(n/1e9).toFixed(2)+'B':n>=1e6?(n/1e6).toFixed(2)+'M':n>=1e4?(n/1e3).toFixed(1)+'k':fmt(n);
const pct=n=>(n*100).toFixed(n<.01?2:1)+'%';
const escapeHtml=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const qualityLabel=quality=>`<span class="quality-label quality-${quality}">${escapeHtml(QUALITY[quality])}</span>`;
const statText=stats=>Object.entries(stats).map(([k,v])=>(STAT_NAMES[k]||k)+' +'+(k==='lifesteal'?Number(v).toFixed(1)+'%':compactNum(v))).join(' · ');
const actionButton=(action,label,data={},disabled=false)=>`<button data-action="${action}" class="${!disabled&&['build','train','hire','boss','equip'].includes(action)?'action-ready':''}" ${Object.entries(data).map(([k,v])=>`data-${k}="${escapeHtml(v)}"`).join(' ')} ${disabled?'disabled':''}>${label}</button>`;
function cached(id,key,html){if(caches[id]===key)return;caches[id]=key;$(id).innerHTML=html();}
function notice(text){$('notice').textContent=text;noticeUntil=Date.now()+5000;}
function save(){engine.s.savedAt=Date.now();engine.s.bossInProgress=engine.enemy?.kind==='boss';try{localStorage.setItem(SAVE_KEY,JSON.stringify(engine.s));$('saveStatus').textContent='进度已保存 · v0.7.4';}catch(e){storageOK=false;$('saveStatus').textContent='浏览器存档不可用';}}
function setTab(next){tab=next;for(const name of ['adventure','camp','equipment','army','workshop','market','rules'])$(name+'View').hidden=name!==next;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===next));$('pageTitle').textContent={adventure:'冒险',camp:'营地',equipment:'装备',materials:'材料',army:'部队',workshop:'工坊',market:'商栈',rules:'规则'}[next];render();}
function costText(cost){return Availability.resources(engine,cost).map(r=>`${r.name} ${fmt(r.required)}（${fmt(r.owned)}）`).join(' · ');}
function costChips(cost,showStatus=true){return '<div class="resource-costs">'+Availability.resources(engine,cost).map(r=>`<span class="resource-cost ${r.enough?'is-enough':'is-short'}"><span>${r.name}</span><b>${fmt(r.owned)} / ${fmt(r.required)}</b>${showStatus?`<small>${r.enough?'✓ 充足':'缺 '+fmt(r.shortfall)}</small>`:''}</span>`).join('')+'</div>';}
function stateBadge(state){return `<span class="availability-badge is-${state.kind}">${state.label}</span>`;}
function staticAction(id,state,label){const button=$(id);button.disabled=state.kind!=='ready';button.classList.toggle('action-ready',state.kind==='ready');button.textContent=state.kind==='ready'?label:state.kind==='short'?'资源不足':state.kind==='max'?'已满级':'条件未满足';button.title=state.reason||state.label;}
function renderAvailability(){const ready=BUILDINGS.filter(b=>Availability.building(engine,b).kind==='ready'),badge=$('campReadyBadge');badge.hidden=!ready.length;badge.textContent=ready.length;badge.title='可建造 '+ready.filter(b=>!engine.lv(b.id)).length+' 项、可升级 '+ready.filter(b=>engine.lv(b.id)).length+' 项';}
function renderBattle(){const s=engine.s,st=engine.stats(),e=engine.enemy,r=REGIONS[s.region];$('modeLabel').textContent=s.mode==='camp'?(s.deadUntil>0?'死亡休整':'营地恢复'):s.mode==='combat'?'正在交战':'自动探索';$('battleRegion').textContent=r.name;$('lordLevel').textContent='Lv. '+s.level;$('hpText').textContent=fmt(s.hp)+' / '+fmt(st.hp);$('hpBar').style.width=Math.max(0,s.hp/st.hp*100)+'%';$('recoveryText').textContent=s.mode==='camp'?(s.deadUntil>0?'休整 '+Math.ceil(s.deadUntil)+' 秒':'每秒恢复 '+fmt(st.hp*(.025+engine.lv('infirmary')*.01))):'生命 '+Math.floor(s.hp/st.hp*100)+'%';$('enemyKind').textContent=e?(e.kind==='boss'?'区域首领':e.kind==='elite'?(e.rare?'稀有精英':'精英怪物'):'普通怪物'):'等待交战';$('enemyName').textContent=e?e.name:s.mode==='camp'?'队伍正在营地休整':'搜索附近的敌人';$('enemyHp').textContent=e?fmt(e.hp)+' / '+fmt(e.maxHp):'—';$('enemyBar').style.width=e?Math.max(0,e.hp/e.maxHp*100)+'%':'0%';$('enemyTiming').textContent=e?'交战 '+Math.floor(engine.battleSeconds)+' 秒':'';$('enemyStats').textContent=e?'攻击 '+compactNum(e.attack)+' · 防御 '+compactNum(e.defense)+' · 间隔 '+e.interval.toFixed(1)+' 秒':'普通与精英自动交战，首领须手动挑战';$('teamSummary').textContent='佣兵 '+fmt(engine.troopCount())+' / '+fmt(engine.troopCap())+' · 怪物 '+fmt(engine.monsterCount())+' / '+fmt(engine.monsterCap());$('bloodNote').textContent=s.mode==='camp'?'仅营地与吸血恢复生命':'战后不恢复生命 · 自动撤退 '+(s.retreat?s.retreat+'%':'关闭');$('depart').disabled=s.mode!=='camp'||s.deadUntil>0;$('returnCamp').disabled=s.mode==='camp';$('gold').textContent=fmt(s.gold);$('power').textContent=compactNum(st.power);$('profileLevel').textContent='Lv. '+s.level;
 const extra={insight:'穿透 '+pct(Math.min(.65,st.insight/(st.insight+160))),speed:st.interval.toFixed(2)+'秒/次',greed:'普通材料 '+pct(engine.lootChance('normal',st).material),intimidation:'普通招募 '+pct(engine.recruitChance({kind:'normal'},st)),leadership:'部队 ×'+(1+st.leadership/100).toFixed(2),lifesteal:'每次攻击按伤害恢复'};
 cached('statList',JSON.stringify([st,extra]),()=>Object.keys(STAT_NAMES).map(k=>`<div class="stat-row has-tooltip" tabindex="0" data-tooltip="${escapeHtml(rules[k]+(extra[k]?'\n当前效果：'+extra[k]:''))}" aria-label="${STAT_NAMES[k]} ${k==='lifesteal'?st[k].toFixed(1)+'%':compactNum(st[k])}"><span>${STAT_NAMES[k]}</span><b>${k==='lifesteal'?st[k].toFixed(1)+'%':compactNum(st[k])}</b></div>`).join(''));}
const REGION_DESCRIPTIONS=["古树与苔藓遮住归途，狼嚎从林间传来。","废弃矿道深处，铁石与蛛网一同苏醒。","河湾吞没荒田，旧日农庄已成怪物巢穴。","长风掠过荒原，流亡者追随兽群游荡。","幽光在雾中浮动，毒藤守着湿地的秘密。","煤灰落在残碑上，不眠的亡魂巡行墓园。","暮色笼罩断壁，失落的卫士仍在执勤。","铁木枝根交错，密林深处暗藏吞噬者。","群兽盘踞高地，裂山的咆哮震动岩壁。","冰雪封住山径，凛冬之心仍在跳动。","熔炉终日燃烧，灰烬与符文在烈焰中重生。","巨龙遗骨横跨峡谷，残魂徘徊其间。","月光隐入圣殿，不灭的守卫静候来客。","现实在此碎裂，虚空生灵循着星光而来。","陨星照亮圣所，古老的审判尚未终结。","长夜笼罩王庭，失序的骑士守着最后王座。"];
function regionTooltip(r){return r.name+'\n'+REGION_DESCRIPTIONS[r.id]+'\n\n掉落物品：当地装备（13 部位，普通～至宝）。\n掉落材料：'+r.pool.map(id=>MATERIALS.find(m=>m.id===id).name).join('、')+'\n精英另有机会掉落相邻区域材料。\n区域首领：'+r.bossName+'\n建议战力：'+fmt(r.bossPower);}
function regionTooltipHtml(r){const fields=[['掉落物品','当地装备（13 部位，普通～至宝）'],['掉落材料',r.pool.map(id=>MATERIALS.find(m=>m.id===id).name).join('、')],['区域首领',r.bossName],['建议战力',fmt(r.bossPower)]];return `<div class="region-tip-title">${escapeHtml(r.name)}</div><p class="region-tip-description">${escapeHtml(REGION_DESCRIPTIONS[r.id])}</p><dl class="region-tip-fields">${fields.map(([label,value])=>`<div><dt>${escapeHtml(label)}</dt><dd>${escapeHtml(value)}</dd></div>`).join('')}</dl><p class="region-tip-note">精英另有机会掉落相邻区域材料。</p>`;}
function renderAdventure(){const s=engine.s;cached('mapGrid',JSON.stringify([s.region,s.cleared,s.discovered]),()=>REGIONS.map(r=>{const open=engine.unlocked(r.id);return `<button data-tooltip="${escapeHtml(regionTooltip(r))}" class="map-card ${s.region===r.id?'selected':''} ${open?'':'locked'}" data-action="region" data-id="${r.id}" aria-pressed="${s.region===r.id}"><small>区域 ${String(r.id+1).padStart(2,'0')}</small><strong>${r.name}</strong><span>${s.cleared[r.id]?'已通关':!open?'击败前区首领解锁':s.discovered[r.id]?'已发现首领':'可探索'}</span></button>`;}).join(''));
 const r=REGIONS[s.region],challenge=engine.bossChallengeState(r.id);const status=engine.enemy?.kind==='boss'?'首领挑战中':!s.discovered[r.id]?'探索情报 '+Math.floor(s.scouted[r.id])+' / '+r.scoutNeed:s.cleared[r.id]?'已通关 · '+challenge.label:'首领已定位';
 cached('regionAction',JSON.stringify([r.id,status,challenge]),()=>'<div><b>'+r.name+'</b><span>'+status+'</span></div>'+actionButton('boss',challenge.ready?'挑战首领':challenge.label,{id:r.id},!challenge.ready));
 const events=engine.events.filter(e=>!compact||e.type!=='normal');cached('logList',events.map(e=>e.time+e.text).join('|')+compact,()=>events.slice(-45).map(e=>`<div class="log-line ${e.type}"><time>${String(Math.floor(e.time/3600)).padStart(2,'0')}:${String(Math.floor(e.time/60)%60).padStart(2,'0')}:${String(Math.floor(e.time)%60).padStart(2,'0')}</time><span>${escapeHtml(e.text)}</span></div>`).join(''));$('logList').scrollTop=$('logList').scrollHeight;}
function buildingTooltipHtml(id){const b=BUILDINGS.find(b=>b.id===id),lv=engine.lv(id),state=Availability.building(engine,b);const effectLines={armory:['全队攻击 +5% / 级','全队防御 +5% / 级'],academy:['解锁装备分解','领主洞察 +3 / 级','领袖 +2 / 级'],warehouse:['装备容量 +60 / 级','离线上限 +1 小时 / 级'],market:['金币收益 +5% / 级','贪婪 +3 / 级']}[id]||b.effect.split(/[；;，、]/);const effects=effectLines.map(effect=>escapeHtml(effect.trim())).join('<br>');return '<div class="region-tip-title">'+escapeHtml(b.name)+' · Lv.'+lv+'</div><p class="region-tip-description">'+escapeHtml(b.desc)+'</p><dl class="region-tip-fields"><div><dt>建筑效果</dt><dd>'+effects+'</dd></div></dl>'+(state.kind==='max'?'':'<div class="building-cost-title">升级消耗 <span>现有 / 需要</span></div>'+costChips(engine.buildingCost(b),false));}
function renderCamp(){const s=engine.s;$('campSummary').textContent='主厅 Lv.'+engine.lv('hall');cached('buildingList',JSON.stringify([s.camp,s.gold,s.materials,s.cleared]),()=>BUILDINGS.map(b=>{const lv=engine.lv(b.id),state=Availability.building(engine,b),ready=state.kind==='ready';return `<div class="building-tile" data-tooltip="${escapeHtml(b.name+'：'+b.effect)}" data-building="${b.id}" ${ready?'':'tabindex="0"'}><button class="map-card building-card is-${state.kind}" data-action="build" data-id="${b.id}" ${ready?'':'disabled'} aria-label="${escapeHtml(b.name+' Lv.'+lv+'，'+state.label)}"><strong>${b.name}</strong><span>Lv.${lv}</span></button></div>`;}).join(''));}
function renderTraining(){const s=engine.s;$('autoResume').checked=s.autoResume;$('retreat').value=String(s.retreat);
 cached('trainingList',JSON.stringify([s.training,s.gold,s.camp.hall]),()=>['lord','troop'].map(type=>{const state=Availability.training(engine,type);return `<article class="panel training-card availability-row is-${state.kind}"><div class="row-heading"><b>${type==='lord'?'领主修行':'佣兵训练'} · Lv.${s.training[type]}</b>${stateBadge(state)}</div><p>${type==='lord'?'领主基础与装备生命、攻击、防御每级 ×1.11':'全体佣兵生命、攻击、防御每级 ×1.20'}</p><small>${state.reason||'等级上限 '+engine.lv('hall')*8}</small>${costChips({gold:engine.trainingCost(type)})}${actionButton('train',state.kind==='ready'?'立即训练':state.kind==='short'?'金币不足':'主厅等级限制',{id:type},state.kind!=='ready')}</article>`;}).join(''));}
function showFacility(id){const unlocked=engine.lv(id)>0;$(id+'Locked').hidden=unlocked;$(id+'Content').hidden=!unlocked;return unlocked;}
function renderWorkshop(){if(!showFacility('workshop'))return;const s=engine.s;
 const slot=$('enhanceSlot').value||'mainhand',cost=engine.enhanceCost(slot),rank=s.ranks[slot],enhanceState=Availability.enhancement(engine,slot);$('workshopHint').innerHTML=stateBadge(enhanceState)+' <span>工坊 Lv.'+engine.lv('workshop')+'</span>';$('enhancePreview').textContent=SLOTS[slot].name+' +'+rank+' → +'+(rank+1)+'（属性增幅 '+rank*12+'% → '+(rank+1)*12+'%）';$('enhanceCost').innerHTML=(enhanceState.reason?'<div class="unlock-reason">'+enhanceState.reason+'</div>':'')+costChips(cost);staticAction('enhance',enhanceState,'立即强化');const region=Number($('craftRegion').value||0),craftState=Availability.crafting(engine,region);$('craftCost').innerHTML=stateBadge(craftState)+' <span class="unlock-reason">'+(craftState.reason||'需工坊 Lv.'+(region+1))+'</span>'+costChips(engine.craftCost(region));staticAction('craft',craftState,'立即打造');}
function renderMarket(){if(!showFacility('market'))return;$('marketHint').textContent=engine.lv('market')?'已开放':'建造商栈解锁';$('sellMaterial').disabled=!engine.lv('market');}

function selectedGear(){return engine.s.bag.find(i=>i.id===selectedItem)||Object.values(engine.s.equipped).find(i=>i?.id===selectedItem);}
function renderLiveEquipment(){const s=engine.s;cached('slotGrid',JSON.stringify([s.equipped,s.ranks]),()=>Object.entries(SLOTS).map(([slot,v])=>{const i=s.equipped[slot],rank=s.ranks[slot]||0,label=i?i.name+' +'+rank:'未装备',enhanced=i?Object.fromEntries(Object.entries(i.stats).map(([k,n])=>[k,n*(1+.12*rank)])):null,tip=i?i.name+' +'+rank+' · '+QUALITY[i.quality]+'\n'+v.name+' · '+REGIONS[i.region].name+'\n'+statText(enhanced)+'\n槽位强化 +'+rank+'（属性增幅 '+rank*12+'%）':v.name+' · 未装备';return `<button class="slot-cell has-tooltip" data-slot="${slot}" data-action="inspect" data-id="${i?.id||''}" data-tooltip="${escapeHtml(tip)}" aria-label="${escapeHtml(v.name+'：'+label)}"><small>${v.name}</small><strong class="${i?'gear-name quality-'+i.quality:''}">${escapeHtml(label)}</strong></button>`;}).join(''));}
function renderEquipment(){const s=engine.s;$('bagCount').textContent='行囊 '+s.bag.length+' / '+engine.bagCap();$('autoEquip').checked=s.autoEquip;$('autoSell').checked=s.autoSell;const slot=$('bagFilter').value,q=$('qualityFilter').value,items=s.bag.filter(i=>(slot==='all'||i.slot===slot)&&(q==='all'||i.quality===Number(q)));cached('bagList',JSON.stringify([items.map(i=>i.id),slot,q]),()=>items.length?[...items].reverse().map(i=>`<button class="bag-item" data-action="inspect" data-id="${i.id}"><b><span class="gear-name quality-${i.quality}">${escapeHtml(i.name)}</span> · ${qualityLabel(i.quality)}</b><small>${SLOTS[i.slot].name} · ${REGIONS[i.region].name}</small><small>${statText(i.stats)}</small></button>`).join(''):'<div class="empty">暂无符合条件的装备。</div>');const i=selectedGear(),inBag=i&&s.bag.some(x=>x.id===i.id);cached('itemInspector',JSON.stringify([i,inBag,s.camp.academy,s.ranks]),()=>!i?'<span>点击槽位或行囊中的装备，直接查看属性与操作。</span>':`<h3><span class="gear-name quality-${i.quality}">${escapeHtml(i.name)}</span> · ${qualityLabel(i.quality)}</h3><p>${SLOTS[i.slot].name} · ${REGIONS[i.region].name} · 综合评分 ${fmt(engine.itemScore(i))}</p><p>${statText(i.stats)}</p><p>槽位强化 +${s.ranks[i.slot]}，所有词条 ×${(1+s.ranks[i.slot]*.12).toFixed(2)}。综合评分仅供参考，特殊属性请自行取舍。</p><div class="actions">${actionButton('equip',inBag?'穿戴':'已穿戴',{id:i.id},!inBag)}${actionButton('sellGear','出售 · '+fmt(engine.salePrice(i))+' 金',{id:i.id},!inBag)}${actionButton('salvage','分解',{id:i.id},!inBag||!engine.lv('academy'))}</div>`);}
function renderMaterials(){const s=engine.s,visible=MATERIALS.filter(m=>REGIONS.some(r=>engine.unlocked(r.id)&&r.pool.includes(m.id)));cached('materialList',JSON.stringify([s.materials,s.cleared]),()=>visible.map(m=>`<div class="material-row"><span tabindex="0" data-tooltip="${escapeHtml('产地：'+REGIONS.filter(r=>engine.unlocked(r.id)&&r.pool.includes(m.id)).map(r=>r.name).join(' / '))}">${m.name}</span><b>${fmt(s.materials[m.id])}</b></div>`).join(''));}
function renderArmy(){const s=engine.s,st=engine.stats(),count=Number($('hireCount').value);$('troopCap').textContent=fmt(engine.troopCount())+' / '+fmt(engine.troopCap());$('monsterCap').textContent=fmt(engine.monsterCount())+' / '+fmt(engine.monsterCap());cached('troopList',JSON.stringify([s.gold,s.troops,s.training.troop,s.camp.barracks,count]),()=>TROOPS.map(t=>{const cost=engine.hireCost(t.id,count);return `<div class="manage-row"><div class="text"><b>${t.name}</b><span class="badge">${fmt(s.troops[t.id])} 人</span><p>单人基础：生命 ${t.hp} / 攻击 ${t.attack} / 防御 ${t.defense}</p><small>受佣兵训练、兵营、领袖与军械库加成。雇佣 ${count} 人消耗 ${fmt(cost)} 金。</small></div>${actionButton('hire','雇佣 '+count+' 人',{id:t.id,count},s.gold<cost||engine.troopCount()+count>engine.troopCap())}</div>`;}).join(''));cached('recruitedList',JSON.stringify([s.monsters,s.camp.beastpen]),()=>Object.values(s.monsters).length?Object.values(s.monsters).sort((a,b)=>b.region-a.region).map(m=>`<div class="manage-row"><div class="text"><b>${m.name}</b><span class="badge">${m.kind==='boss'?'首领':m.kind==='elite'?'精英':'普通'} · ${m.count} 只</span><p>单只基础：生命 ${compactNum(m.hp)} / 攻击 ${compactNum(m.attack)} / 防御 ${compactNum(m.defense)}</p><small>${REGIONS[m.region].name} · 受驯兽场与领袖加成</small></div></div>`).join(''):'<div class="empty">暂无招募怪物。威慑高于 0 后，战胜怪物有机会招募；建造驯兽场可获得初始威慑。</div>');$('contribution').innerHTML=[['领主',st.lord],['雇佣兵',st.troop],['招募怪物',st.monster]].map(([name,v])=>`<div class="manage-row"><div class="text"><b>${name}</b><p>生命 ${compactNum(v.hp)} / 攻击 ${compactNum(v.attack)} / 防御 ${compactNum(v.defense)}</p></div></div>`).join('');}
function render(){const clear=engine.events.findLast(e=>e.data?.kind==='boss-clear');if(clear&&clear!==lastBossClear){lastBossClear=clear;notice(clear.text);noticeUntil=Date.now()+12000;save();}renderBattle();renderLiveEquipment();feedback.render();renderAvailability();if(tab==='adventure')renderAdventure();if(tab==='camp')renderCamp();if(tab==='equipment')renderEquipment();renderMaterials();if(tab==='army'){renderTraining();renderArmy();}if(tab==='workshop')renderWorkshop();if(tab==='market')renderMarket();if(noticeUntil&&Date.now()>noticeUntil){$('notice').textContent='';noticeUntil=0;}}
function mutate(fn,success=''){const before=engine.events.at(-1),result=fn();if(result===false)notice(engine.events.at(-1)!==before?engine.events.at(-1).text:'条件尚未满足，请检查金币、材料、容量与前置要求。');else if(success)notice(success);save();render();return result;}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));
document.querySelector('main').addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b||b.disabled)return;const d=b.dataset,id=d.id;switch(d.action){case'region':mutate(()=>engine.selectRegion(Number(id)));break;case'boss':if(mutate(()=>engine.challenge(Number(id)),'已开始首领挑战：'+REGIONS[Number(id)].bossName+'，击败后解锁下一区域。'))document.querySelector('.battle').scrollIntoView({block:'start',behavior:'instant'});break;case'build':mutate(()=>engine.build(id),'建筑升级完成');break;case'train':mutate(()=>engine.train(id),'训练完成');break;case'hire':mutate(()=>engine.hire(id,Number(d.count)),'佣兵已加入队伍');break;case'inspect':selectedItem=id||null;if(d.slot){$('bagFilter').value=d.slot;$('qualityFilter').value='all';}setTab('equipment');$('itemInspector').scrollIntoView({block:'nearest',behavior:'instant'});break;case'equip':mutate(()=>engine.equip(id),'已穿戴');break;case'sellGear':mutate(()=>engine.sellItem(id),'已出售');break;case'salvage':mutate(()=>engine.salvage(id),'已分解');break;}});
$('depart').onclick=()=>mutate(()=>engine.start());$('returnCamp').onclick=()=>mutate(()=>engine.returnCamp(true));$('compactLog').onchange=()=>{compact=$('compactLog').checked;renderAdventure();};$('autoResume').onchange=()=>{engine.s.autoResume=$('autoResume').checked;if(!engine.s.autoResume)engine.s.resume=false;save();};$('retreat').onchange=()=>{engine.s.retreat=Number($('retreat').value);save();};$('autoEquip').onchange=()=>{engine.s.autoEquip=$('autoEquip').checked;save();};$('autoSell').onchange=()=>{engine.s.autoSell=$('autoSell').checked;save();};
$('enhance').onclick=()=>mutate(()=>engine.enhance($('enhanceSlot').value),'强化完成');$('craft').onclick=()=>mutate(()=>engine.craft(Number($('craftRegion').value),$('craftSlot').value),'打造完成');$('sellMaterial').onclick=()=>mutate(()=>engine.sellMaterial($('sellMaterialId').value,Number($('sellMaterialCount').value)),'材料已出售');for(const id of ['enhanceSlot','craftRegion','craftSlot'])$(id).onchange=renderWorkshop;for(const id of ['bagFilter','qualityFilter'])$(id).onchange=renderEquipment;$('hireCount').onchange=renderArmy;
for(const [slot,v]of Object.entries(SLOTS)){for(const id of ['enhanceSlot','craftSlot','bagFilter']){const o=document.createElement('option');o.value=slot;o.textContent=v.name;$(id).append(o);}}$('enhanceSlot').value='mainhand';$('craftSlot').value='mainhand';REGIONS.forEach(r=>{const o=document.createElement('option');o.value=r.id;o.textContent=String(r.id+1).padStart(2,'0')+' · '+r.name;$('craftRegion').append(o);});MATERIALS.forEach(m=>{const o=document.createElement('option');o.value=m.id;o.textContent=m.name+'（'+m.price+' 金）';$('sellMaterialId').append(o);});QUALITY.forEach((q,n)=>{const o=document.createElement('option');o.value=n;o.textContent=q;$('qualityFilter').append(o);});
const rules={hp:'全队当前生命上限；装备、领主、佣兵和怪物共同贡献。战后不自动回复。',attack:'决定每次攻击伤害；领主、佣兵和怪物共同贡献。',defense:'每次受到的伤害扣除防御的 70%，至少承受 1 点。',insight:'提高暴击率与防御穿透，并加快首领情报积累。',speed:'缩短全队攻击间隔，最快每 0.35 秒攻击一次。',greed:'提高材料和装备掉落概率，收益递减；不增加金币本身。',intimidation:'胜利后有概率招募当前怪物；精英与首领的成功率更低。',leadership:'每 1 点令所有佣兵和招募怪物的属性增加 1%。',lifesteal:'每次攻击按实际伤害的一定百分比恢复生命，上限 25%。'};$('statRules').innerHTML=Object.entries(rules).map(([id,text])=>`<div class="rule-row"><b>${STAT_NAMES[id]}</b><span>${text}</span></div>`).join('');
// A single tooltip keeps details readable without expanding the overview.
const infoTooltip=$('infoTooltip');let tooltipTarget=null;
function hideInfoTooltip(){if(tooltipTarget)tooltipTarget.removeAttribute('aria-describedby');tooltipTarget=null;infoTooltip.hidden=true;}
function equipmentTooltipHtml(slot){const item=engine.s.equipped[slot],rank=engine.s.ranks[slot]||0;const fields=item?Object.entries(item.stats).map(([key,value])=>[STAT_NAMES[key]||key,'+'+(key==='lifesteal'?(value*(1+.12*rank)).toFixed(1)+'%':compactNum(value*(1+.12*rank)))]):[['装备状态','未装备']];return `<div class="region-tip-title ${item?'gear-name quality-'+item.quality:''}">${escapeHtml(item?item.name+' +'+rank:SLOTS[slot].name+' · 未装备')}</div><dl class="region-tip-fields">${item?`<div><dt>品质</dt><dd>${qualityLabel(item.quality)}</dd></div>`:''}${fields.map(([label,value])=>`<div><dt>${escapeHtml(label)}</dt><dd>${escapeHtml(value)}</dd></div>`).join('')}</dl>`;}
function showInfoTooltip(target){if(!target)return;hideInfoTooltip();tooltipTarget=target;const region=target.matches('.map-card')?REGIONS[Number(target.dataset.id)]:null,slot=target.matches('.slot-cell')?target.dataset.slot:null;const building=target.closest('[data-building]')?.dataset.building;infoTooltip.classList.toggle('region-tooltip',!!region||!!slot||!!building);infoTooltip.classList.toggle('building-tooltip',!!building);infoTooltip.classList.toggle('equipment-tooltip',!!slot);if(building)infoTooltip.innerHTML=buildingTooltipHtml(building);else if(region)infoTooltip.innerHTML=regionTooltipHtml(region);else if(slot)infoTooltip.innerHTML=equipmentTooltipHtml(slot);else infoTooltip.textContent=target.dataset.tooltip;target.setAttribute('aria-describedby','infoTooltip');infoTooltip.hidden=false;const rect=target.getBoundingClientRect(),box=infoTooltip.getBoundingClientRect();infoTooltip.style.left=Math.max(8,Math.min(rect.left,window.innerWidth-box.width-8))+'px';infoTooltip.style.top=Math.max(8,rect.bottom+box.height+10<=window.innerHeight?rect.bottom+7:rect.top-box.height-7)+'px';}
document.addEventListener('pointerover',e=>{const target=e.target.closest('[data-tooltip]');if(target&&target!==tooltipTarget)showInfoTooltip(target);});
document.addEventListener('pointerout',e=>{if(tooltipTarget&&tooltipTarget.contains(e.target)&&!tooltipTarget.contains(e.relatedTarget))hideInfoTooltip();});
document.addEventListener('focusin',e=>showInfoTooltip(e.target.closest('[data-tooltip]')));
document.addEventListener('focusout',hideInfoTooltip);document.addEventListener('keydown',e=>{if(e.key==='Escape')hideInfoTooltip();});
window.addEventListener('scroll',hideInfoTooltip,true);window.addEventListener('resize',hideInfoTooltip);
const feedback=new BattleFeedback(engine);$('motionToggle').checked=feedback.enabled;$('motionToggle').onchange=()=>feedback.setEnabled($('motionToggle').checked);
render();let last=Date.now(),lastSave=Date.now();setInterval(()=>{const now=Date.now(),dt=(now-last)/1000;last=now;if(dt>5){engine.offline(dt,{resumeBoss:true});feedback.sync();}else engine.tick(Math.min(2,dt));render();if(now-lastSave>5000){save();lastSave=now;}},1000);window.addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.hidden)save();});
